package br.com.nuvemtv;
import android.annotation.SuppressLint;import android.webkit.*;import android.os.*;import android.content.*;import org.json.*;import java.util.concurrent.*;
final class WebPlayer {
 final WebView view;final Cloud cloud;final Pad pad;final NativePlayer.Ui ui;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();volatile boolean closed;String lastPad="";
 @SuppressLint({"SetJavaScriptEnabled","AddJavascriptInterface"}) WebPlayer(Context c,Cloud cloud,Pad pad,int height,int kbps,String codec,boolean stats,boolean microphone,String title,NativePlayer.Ui ui){this.cloud=cloud;this.pad=pad;this.ui=ui;view=new WebView(c);WebSettings s=view.getSettings();s.setJavaScriptEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setDomStorageEnabled(false);s.setCacheMode(WebSettings.LOAD_NO_CACHE);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);
  view.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest request){
   if(!closed&&microphone&&c.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==android.content.pm.PackageManager.PERMISSION_GRANTED&&"https://appassets.androidplatform.net".equals(request.getOrigin().toString().replaceAll("/+$",""))&&java.util.Arrays.asList(request.getResources()).contains(PermissionRequest.RESOURCE_AUDIO_CAPTURE))request.grant(new String[]{PermissionRequest.RESOURCE_AUDIO_CAPTURE});else request.deny();
  }});
  view.addJavascriptInterface(new Bridge(),"CloudBridge");view.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(!r.getUrl().toString().startsWith("https://appassets.androidplatform.net/"))return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));String path=r.getUrl().getPath();if(!"/player.html".equals(path)&&!"/player.js".equals(path))return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));try{return new WebResourceResponse(path.endsWith(".js")?"application/javascript":"text/html","UTF-8",c.getAssets().open(path.substring(1)));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));}}
   @Override public void onPageFinished(WebView v,String url){if(!closed)v.evaluateJavascript("boot("+Json.obj("height",height,"kbps",kbps,"codec",codec,"stats",stats,"microphone",microphone,"title",title)+")",null);}
  });view.loadUrl("https://appassets.androidplatform.net/player.html");main.post(pads);
 }
 final Runnable pads=new Runnable(){public void run(){if(closed)return;String state=Json.obj("buttons",pad.buttons,"axes",Json.arr(pad.axes[0],pad.axes[1],pad.axes[2],pad.axes[3],pad.axes[4],pad.axes[5])).toString();if(!state.equals(lastPad)){lastPad=state;view.evaluateJavascript("window.pad="+state,null);}main.postDelayed(this,20);}};
 final class Bridge {
  @JavascriptInterface public void call(String id,String action,String payload){if(closed)return;worker.execute(()->{try{JSONObject p=Json.parse(payload);Object out;switch(action){case "start":cloud.start(p.getString("title"),p.getInt("height"),ui::status);out=Json.obj("pulse",cloud.pulse);break;case "offer":out=cloud.offer(p.getString("sdp"));break;case "chatOffer":out=cloud.chatOffer(p.getString("sdp"));break;case "ice":out=cloud.ice(p.getJSONArray("candidates"));break;case "keepalive":out=cloud.call("POST","keepalive",new JSONObject());break;default:throw new Exception("Operação inválida");}reply(id,out,null);}catch(Exception e){reply(id,null,e.getMessage());}});}
  @JavascriptInterface public void status(String s){if(!closed)ui.status(s);}
  @JavascriptInterface public void stats(String s){if(!closed)ui.stats(s);}
  @JavascriptInterface public void connected(){if(!closed)ui.connected();}
  @JavascriptInterface public void error(String s){if(!closed)ui.error(new Exception(s));}
 }
 void reply(String id,Object value,String error){main.post(()->{if(!closed)view.evaluateJavascript("settle("+JSONObject.quote(id)+","+(value==null?"null":value.toString())+","+(error==null?"null":JSONObject.quote(error))+")",null);});}
 void close(){if(closed)return;closed=true;cloud.stopped=true;main.removeCallbacksAndMessages(null);pad.reset();view.evaluateJavascript("shutdown()",null);view.removeJavascriptInterface("CloudBridge");view.stopLoading();view.destroy();worker.execute(()->{cloud.stop();worker.shutdown();});}
}
